			if(a[i]==0&& b[i]==0) break;
			if(a[i]>b[i])swap(a,b,i);
			System.out.println(a[i]+" "+b[i]);
		}
	}

	static void swap(int[] a,int[] b,int i){
		int tmp =a[i];
		a[i]=b[i];
		b[i]=tmp;
		return;
	}

}

