		} catch (Exception e) {
			e.printStackTrace();
		}
	}

	private static String checkNum(int n) {
		StringBuilder sb = new StringBuilder();
		for (int i = 1; i <= n; i++) {
			if (i % 3 == 0) {
				sb.append(' ').append(String.valueOf(i));
			} else if (String.valueOf(i).contains("3")) {
				sb.append(' ').append(String.valueOf(i));
			}
		}
		return sb.toString();
	}
}

