                    if (a != n) {
                        for (int i = 0; i < m; i++) {
                            matrix_A[a][i] = Integer.parseInt(st.nextToken());
                        }
                        a++;
                    } else {
                        for (int i = 0; i < l; i++) {
                            matrix_B[b][i] = Integer.parseInt(st.nextToken());
                        }
                        b++;
                    }
                }
            }
            if (a == n && b == m) {
                break;
            }
        }

