                    } else {
                        w[j - h] = w[j];
                    }
                }
                for (j = 0; j < h; j++) {
                    w[l - h + j] = R[j];
                }
            }
            for (i = 0; i < l; i++) {
                System.out.printf("%c", w[i]);
            }
            System.out.printf("\n");
        }
    }
}

