import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;

public class Main {
	public static void main (String[] args) throws IOException
	{
		BufferedReader input = new BufferedReader (new InputStreamReader (System.in));

		boolean set = true;

		int count = 0;

		ArrayList<String> result = new ArrayList<String>();

		//シャッフルを始める
		while(set)
		{
			//データを入力する
			String str = input.readLine();

			//終了条件
			if(str.equals("-"))
			{
				for(int num = 0; num < count; num++)
					System.out.println(result.get(num));

				break;
			}

			//カードごとに分ける
				char[] cards = str.toCharArray();

			int kaisuu = Integer.parseInt(input.readLine());

			int[] maisuu = new int[kaisuu];

			//カードをとる枚数を入力する
			for(int num = 0; num < kaisuu; num++)
				maisuu[num] = Integer.parseInt(input.readLine());

			char[] over = new char[cards.length];

			//シャッフルする
			for(int kai = 0; kai < kaisuu; kai++)
			{
				for(int mai = 0; mai < cards.length; mai++)
				{
					if(mai + maisuu[kai] < cards.length)
						over[mai] = cards[mai + maisuu[kai]];
					else
					{
						over[mai] = cards[mai + maisuu[kai] - cards.length];
					}
				}

				for(int num = 0; num < cards.length; num++)
					cards[num] = over[num];

			}

			result.add(String.valueOf(cards));

			count++;

		}
	}
}

import java.util.Scanner;

public class Main {
  public static int head, tail;
  private final static int MAX = 100000;
  private static char[] Queue = new char[MAX];

  public static void main(String[] args) {

    Scanner sc = new Scanner(System.in);
    while (true) {
      char[] S = sc.next().toCharArray();
      initialize();
      for (char s : S)
        enqueue(s);
      if (Character.toString(S[0]).equals("-"))
        break;
      int n = sc.nextInt();
      for (int i = 0; i < n; i++) {
        int m = sc.nextInt();
        for (int j = 0; j < m; j++) {
          enqueue(dequeue());
        }
      }
      for (int i = head; i < tail; i++) {
        System.out.print(Queue[i]);
      }
      System.out.println();
    }
  }

  private static void initialize() {
    head = tail = 0;
  }

  private static boolean isEmpty() {
    return head == tail;
  }

  private static boolean isFull() {
    return head == (tail + 1) % MAX;
  }

  private static void enqueue(char x) {
    if (isFull()) {
      throw new Error("Queue Over Flow");
    }
    Queue[tail] = x;
    tail = (tail + 1) % MAX;
  }

  private static char dequeue() {
    if (isEmpty()) {
      throw new Error("Queue Under Flow");
    }
    char x = Queue[head];
    head = (head + 1) % MAX;
    return x;
  }

}

