			int ss = (int)s.get(i);
			if(ss != 0) {
				if(a%ss == 0 && b%ss == 0 && c%ss == 0) {
					while(true) {
						d *= ss;
						a /= ss;
						b /= ss;
						c /= ss;
						if(!(a%ss == 0 && b%ss == 0 && c%ss == 0)) break;
					}
				}
			}
		}
		return d;
	}
