        for (int i = 1; i <= N; i++) {
            for (int j = 1; j <= i; j++) {
                for (int k = 1; k <= j; k++) {
                    int count = Math.max(Math.max(i, j), k);
                    while (count > 0) {
                        if (i == j && j == k) {
                            sum += count;
                            break;
                        } else {
                            if (i % count == 0 && j % count == 0 && k % count == 0) {
