	static long gcd(int a, int b, int c) {
		if(a == b && b == c) {
			return a;
		}
		return gcd(gcd(a,b),c);
	}

	static long gcd(long a, long b) {
		while(true) {
			if(a==b) {
				return a;
			}
			if(a>b) {
				a %= b;
				if(a==0) return b;
			}else {
				b %= a;
				if(b==0) return a;
			}
		}
	}

