						gcd3 = gcd(gcd, k);
						dp[gcd][k] = gcd3;
					} else {
						gcd3 = dp[gcd][k];
					}
					res += gcd3;
				}
			}
		}
		System.out.println(res);
	}

	private static int gcd(int i, int j) {
		while (i != 0 && j != 0) {
			if (i < j) {
				j %= i;
			} else {
				i %= j;
			}
		}
		return Math.max(i, j);
	}
}

