class SolABC162_c {
	int K;
	int[] mu, prime;

	public SolABC162_c(int K) {
		this.K = K;
		mu = new int[K + 1];
		prime = new int[K + 1];
		for (int i = 1; i <= K; ++i) {
			mu[i] = 1;
			prime[i] = 1;
		}
	}

	void calcMu() {
		for (int i = 2; i <= K; ++i) {
			if (prime[i] == 1) {
				for (int j = i; j <= K; j += i) {
					if (j > i)
						prime[j] = 0;
					if (j % (i * i) == 0)
						mu[j] = 0;
					mu[j] = -mu[j];
				}
			}
		}
	}

	void calcGCDTuple(int cnt) {
		long res = 0;
		for (int d = 1; d <= K; ++d) {
			long tmp = 0;
			for (int s = 1; s <= K / d; ++s) {
				tmp += (mu[s] * Math.pow(K / (d * s), cnt));
			}
			res += tmp * d;
		}
		System.out.println(res);
	}
}

