		Arrays.sort(S, 0, N);
		int max = 0;
		int cnt = 1;
		List<String> list = new LinkedList<String>();
		for(int i=1;i<N+1;i++) {
			if(!S[i-1].equals(S[i])) {
				// 切れ目
				if(max < cnt) {
					// 更新
					list.clear();
					max = cnt;
					list.add(S[i-1]);
				}else if (max == cnt){
					// 追加
					list.add(S[i-1]);
				}
				cnt = 1;
			}else {
				// 継続
				cnt++;
			}
		}
		for(String s : list) {
			out.println(s);
		}
	}
}

