    static void solve()
    {
        int H = ni();
        int N = ni();
        List<Integer> list = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            list.add(ni());
        }
        int sum = 0;
        for (int i = 0; i < N; i++) {
            sum += list.get(i);
        }

