            A[i] = Integer.parseInt(sc.next());
        }

        solve(N, Q, K, A);
    }

    public static String solve(int n, int q, long k, int[] a) {
        long[] dp = new long[n];
        for (int i = 0; i < q; i++) {
            int winner = a[i];
            dp[winner - 1] = dp[winner - 1] + 1;
        }

        for (long element : dp) {
            System.out.println(q - k >= element ? "No" : "Yes");
        }
        return null;
    }
}

