    static class BBuffet {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int[] a = in.nextIntArray(n);
            int[] gain = in.nextIntArray(n);
            int[] gainAfter = in.nextIntArray(n - 1);

            int ret = 0;
            int prev = Integer.MAX_VALUE;
            for (int i = 0; i < n; i++) {
                int ith = a[i] - 1;
                ret += gain[ith];
                if (prev + 1 == ith) {
                    ret += gainAfter[prev];
                }
                prev = ith;
            }

            out.println(ret);
        }

    }

