        solver.solve(1, in, out);
        out.close();
    }

    static class CTypicalStairs {
        public void solve(int testNumber, InputReader sc, OutputWriter out) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            long mod = 1000000007;
            long dp[] = new long[n + 1];
            for (int i = 0; i < m; i++) {
                int ii = sc.nextInt();
                dp[ii] = -1;
            }
            dp[n] = 1;
            for (int i = n - 1; i >= 0; i--) {
                if (dp[i] == -1)
                    continue;
                int j = i + 1;
                int k = i + 2;
                if (dp[j] != -1)
                    dp[i] += dp[j] % mod;
                dp[i] %= mod;
                if (j == n)
                    continue;
                if (dp[k] != -1)
                    dp[i] += dp[k] % mod;
                dp[i] %= mod;
            }
            out.println(dp[0]);
        }

    }

