public class Main {
    String s;
    int N;
    private void solve() {
        s = next();
        N = s.length();

        int ans = 0;
        int len = 0;
        for(int i = 0;i < N;i++) {
            if (s.charAt(i) != 'A' && s.charAt(i) != 'C' && s.charAt(i) != 'G' && s.charAt(i) != 'T') {
                len = 0;
            } else {
                len++;
            }

            ans = Math.max(ans, len);
        }

        out.println(ans);
    }

    public static void main(String[] args) {
        out.flush();
        new Main().solve();
        out.close();
    }

    /* Input */
    private static final InputStream in = System.in;
    private static final PrintWriter out = new PrintWriter(System.out);
    private final byte[] buffer = new byte[4096];
    private int p = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (p < buflen)
            return true;
        p = 0;
        try {
            buflen = in.read(buffer);
        } catch (IOException e) {
            e.printStackTrace();
        }
        if (buflen <= 0)
            return false;
        return true;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrint(buffer[p])) {
            p++;
        }
        return hasNextByte();
    }

    private boolean isPrint(int ch) {
        if (ch >= '!' && ch <= '~')
            return true;
        return false;
    }

    private int nextByte() {
        if (!hasNextByte())
            return -1;
        return buffer[p++];
    }

    public String next() {
        if (!hasNext())
            throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = -1;
        while (isPrint((b = nextByte()))) {
            sb.appendCodePoint(b);
        }
        return sb.toString();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }
}

import java.util.*;
public class Main {

	/*
	 * 122B - 3rd Solution
	 * 
	 * We will loop through the right end point of the possible substring
	 * We will also store (lst) which is the last index where it is not a ACGT character
	 * If the right endpoint is not an AGCT character update lst
	 * We know that [lst+1, i] is a possible substring so update answer
	 * 
	 * Time Complexity O(N), Memory Complexity O(N)
	 * 
	 */

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		String s = sc.next();
		int N = s.length();
		int ans = 0, lst = -1;
		for(int i = 0; i<N; i++) {
			if(s.charAt(i) != 'A' && s.charAt(i) != 'C' && s.charAt(i) != 'G' && s.charAt(i) != 'T') {
				lst = i;
			}
			ans = Math.max(ans, i-lst);
		}
		System.out.println(ans);
	}
}

