        for(int i = 0;i < N;i++) {
            for(int j = i + 1;j <= N;j++) {
                String t = s.substring(i, j);
                int len = j - i;
                for(int k = 0;k < t.length();k++) {
                    if (t.charAt(k) != 'A' && t.charAt(k) != 'C' && t.charAt(k) != 'G' && t.charAt(k) != 'T') {
                        len = 0;
                        break;
                    }
                }
                ans = Math.max(ans, len);
            }
        }

        out.println(ans);
    }

