	static ArrayList<Integer> func(int n) {
		ArrayList<Integer> ret = new ArrayList<>();
		int num = (int)Math.sqrt((double)n);
		for(int i = 1; i <= num; i++) {
			if (n % i == 0) {
				int j = n / i;
				if (!ret.contains(i))ret.add(i);
				if (!ret.contains(j))ret.add(j);
			}
		}
		return ret;
	}

