public class Main {


	public static void main(String[] args) {

		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		InputReader sc = new InputReader(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		Solver solver = new Solver();
//		int t = sc.nextInt();
		int t = 1;
		while(t--!=0) {
			solver.solve(sc, out);
		}		
		out.close();

	}

	static int N;
	static long[] arr;
	static long INF = (long) 1e11;
	static long[] dp;
	static int K;

	static class Solver {
		public void solve(InputReader sc, PrintWriter out) {
			N = sc.nextInt();
			K = sc.nextInt();
			arr = sc.nextLongArray(N);
			dp = new long[N];
			Arrays.fill(dp, -1);
			long ans = rec(0);
			out.println(ans);
		}

		private long rec(int i) {
			if(i==N-1) return 0;
			long nowans = INF;
			for(int j = 1; j <= K; j++) {
				if(i+j>=N) break;
				long nowdis = Math.abs(arr[i]-arr[i+j]);
				if(dp[i+j]==-1) dp[i+j] = rec(i+j);
				nowans = Math.min(nowans, nowdis + dp[i+j]);
			}
			return dp[i] = nowans;
		}
	}

	static class InputReader { 
		private boolean finished = false;

		private InputStream stream;
		private byte[] buf = new byte[1024];
		private int curChar;
		private int numChars;
		private SpaceCharFilter filter;

		public InputReader(InputStream stream) {
			this.stream = stream;
		}

		public int read() {
			if (numChars == -1) {
				throw new InputMismatchException();
			}
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = stream.read(buf);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (numChars <= 0) {
					return -1;
				}
			}
			return buf[curChar++];
		}

		public int peek() {
			if (numChars == -1) {
				return -1;
			}
			if (curChar >= numChars) {
				curChar = 0;
				try {
					numChars = stream.read(buf);
				} catch (IOException e) {
					return -1;
				}
				if (numChars <= 0) {
					return -1;
				}
			}
			return buf[curChar];
		}

		public int nextInt() {
